-- DB: qnfo-audit
-- BACKUP: bak_20261019_ops_jobs_login_scrub
-- Rollback: DELETE FROM remediation_contracts WHERE class = 'fm-ops-jobs-sweep-status-gap'; DELETE FROM failure_modes WHERE fm_key = 'ops-jobs-sweep-status-gap'; DELETE FROM queue_sla WHERE stuck_type = 'ops-job-terminal-retained'; DELETE FROM control_registry WHERE control IN ('ops-jobs-terminal-sweep', 'ops-jobs-payload-redaction'); the blanked text is not restorable on purpose (bak_20261019_ops_jobs_login_scrub holds ids and lengths only, because the content was the leak)
-- spof-review: scrubs stored text and records two existing controls; adds no gate, hold or single point of failure
--
-- LOG-REDACT-3 / agent_issues 100036 (2026-10-19, pillar security; second independent review of the qnfo-ops 2.49.1 commit).
-- WHY (measured 2026-10-19, counts only, no row content read)
-- 1. qnfo-ops deletes ops_jobs rows after 14 days, but only status succeeded, failed or terminated. ops_jobs holds 49 rows:
--    cancelled 40 (oldest 2026-09-13), failed 1, succeeded 8. The one row that holds a login link (found by the first review)
--    is cancelled, so the 14-day sweep never removed it and 2.49.1 only redacts rows written from now on. 7 cancelled rows, all
--    older than a day, match the login-link / one-time-code LIKE shapes below (payload 7, response 0, tool_log 0).
-- 2. Fix in code: the sweep includes cancelled (qnfo-ops 2.49.1). Fix in data (this file): terminal rows older than a day whose
--    payload, response or tool_log match a login-link or one-time-code shape are blanked now, so the leak does not wait for the sweep.
--    A terminal row is never replayed (job-load reads payload only for a job that is starting), so nothing reads the blanked text.
-- The LIKE shapes were validated on counts only (SELECT COUNT with each pattern); they over-match on purpose (a % spans the whole
-- text), which at worst blanks an old terminal payload that held no secret.
-- The backup table holds ids, status, timestamps and text lengths ONLY, never content.

CREATE TABLE IF NOT EXISTS bak_20261019_ops_jobs_login_scrub AS SELECT id, status, updated_at, length(payload) AS payload_len, length(response) AS response_len, length(tool_log) AS tool_log_len FROM ops_jobs
  WHERE status IN ('succeeded', 'failed', 'terminated', 'cancelled')
    AND updated_at < strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1 day')
    AND ((payload LIKE '%magic-link%' OR payload LIKE '%magic_link%' OR payload LIKE '%/login%token=%' OR payload LIKE '%/sign-in%token=%' OR payload LIKE '%/signin%token=%' OR payload LIKE '%/verify%token=%' OR payload LIKE '%/auth%token=%' OR payload LIKE '%/reset%token=%' OR payload LIKE '%/confirm%token=%' OR payload LIKE '%/callback%code=%' OR payload LIKE '%/login%code=%' OR payload LIKE '%verification code%' OR payload LIKE '%sign-in code%' OR payload LIKE '%signin code%' OR payload LIKE '%login code%' OR payload LIKE '%security code%' OR payload LIKE '%one-time code%' OR payload LIKE '%one-time password%' OR payload LIKE '%passcode%' OR payload LIKE '%otp=%')
    OR (response LIKE '%magic-link%' OR response LIKE '%magic_link%' OR response LIKE '%/login%token=%' OR response LIKE '%/sign-in%token=%' OR response LIKE '%/signin%token=%' OR response LIKE '%/verify%token=%' OR response LIKE '%/auth%token=%' OR response LIKE '%/reset%token=%' OR response LIKE '%/confirm%token=%' OR response LIKE '%/callback%code=%' OR response LIKE '%/login%code=%' OR response LIKE '%verification code%' OR response LIKE '%sign-in code%' OR response LIKE '%signin code%' OR response LIKE '%login code%' OR response LIKE '%security code%' OR response LIKE '%one-time code%' OR response LIKE '%one-time password%' OR response LIKE '%passcode%' OR response LIKE '%otp=%')
    OR (tool_log LIKE '%magic-link%' OR tool_log LIKE '%magic_link%' OR tool_log LIKE '%/login%token=%' OR tool_log LIKE '%/sign-in%token=%' OR tool_log LIKE '%/signin%token=%' OR tool_log LIKE '%/verify%token=%' OR tool_log LIKE '%/auth%token=%' OR tool_log LIKE '%/reset%token=%' OR tool_log LIKE '%/confirm%token=%' OR tool_log LIKE '%/callback%code=%' OR tool_log LIKE '%/login%code=%' OR tool_log LIKE '%verification code%' OR tool_log LIKE '%sign-in code%' OR tool_log LIKE '%signin code%' OR tool_log LIKE '%login code%' OR tool_log LIKE '%security code%' OR tool_log LIKE '%one-time code%' OR tool_log LIKE '%one-time password%' OR tool_log LIKE '%passcode%' OR tool_log LIKE '%otp=%'));

UPDATE ops_jobs SET
  payload = CASE WHEN (payload LIKE '%magic-link%' OR payload LIKE '%magic_link%' OR payload LIKE '%/login%token=%' OR payload LIKE '%/sign-in%token=%' OR payload LIKE '%/signin%token=%' OR payload LIKE '%/verify%token=%' OR payload LIKE '%/auth%token=%' OR payload LIKE '%/reset%token=%' OR payload LIKE '%/confirm%token=%' OR payload LIKE '%/callback%code=%' OR payload LIKE '%/login%code=%' OR payload LIKE '%verification code%' OR payload LIKE '%sign-in code%' OR payload LIKE '%signin code%' OR payload LIKE '%login code%' OR payload LIKE '%security code%' OR payload LIKE '%one-time code%' OR payload LIKE '%one-time password%' OR payload LIKE '%passcode%' OR payload LIKE '%otp=%') THEN '[redacted by LOG-REDACT-2]' ELSE payload END,
  response = CASE WHEN (response LIKE '%magic-link%' OR response LIKE '%magic_link%' OR response LIKE '%/login%token=%' OR response LIKE '%/sign-in%token=%' OR response LIKE '%/signin%token=%' OR response LIKE '%/verify%token=%' OR response LIKE '%/auth%token=%' OR response LIKE '%/reset%token=%' OR response LIKE '%/confirm%token=%' OR response LIKE '%/callback%code=%' OR response LIKE '%/login%code=%' OR response LIKE '%verification code%' OR response LIKE '%sign-in code%' OR response LIKE '%signin code%' OR response LIKE '%login code%' OR response LIKE '%security code%' OR response LIKE '%one-time code%' OR response LIKE '%one-time password%' OR response LIKE '%passcode%' OR response LIKE '%otp=%') THEN '[redacted by LOG-REDACT-2]' ELSE response END,
  tool_log = CASE WHEN (tool_log LIKE '%magic-link%' OR tool_log LIKE '%magic_link%' OR tool_log LIKE '%/login%token=%' OR tool_log LIKE '%/sign-in%token=%' OR tool_log LIKE '%/signin%token=%' OR tool_log LIKE '%/verify%token=%' OR tool_log LIKE '%/auth%token=%' OR tool_log LIKE '%/reset%token=%' OR tool_log LIKE '%/confirm%token=%' OR tool_log LIKE '%/callback%code=%' OR tool_log LIKE '%/login%code=%' OR tool_log LIKE '%verification code%' OR tool_log LIKE '%sign-in code%' OR tool_log LIKE '%signin code%' OR tool_log LIKE '%login code%' OR tool_log LIKE '%security code%' OR tool_log LIKE '%one-time code%' OR tool_log LIKE '%one-time password%' OR tool_log LIKE '%passcode%' OR tool_log LIKE '%otp=%') THEN '[redacted by LOG-REDACT-2]' ELSE tool_log END
WHERE status IN ('succeeded', 'failed', 'terminated', 'cancelled')
  AND updated_at < strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-1 day')
  AND ((payload LIKE '%magic-link%' OR payload LIKE '%magic_link%' OR payload LIKE '%/login%token=%' OR payload LIKE '%/sign-in%token=%' OR payload LIKE '%/signin%token=%' OR payload LIKE '%/verify%token=%' OR payload LIKE '%/auth%token=%' OR payload LIKE '%/reset%token=%' OR payload LIKE '%/confirm%token=%' OR payload LIKE '%/callback%code=%' OR payload LIKE '%/login%code=%' OR payload LIKE '%verification code%' OR payload LIKE '%sign-in code%' OR payload LIKE '%signin code%' OR payload LIKE '%login code%' OR payload LIKE '%security code%' OR payload LIKE '%one-time code%' OR payload LIKE '%one-time password%' OR payload LIKE '%passcode%' OR payload LIKE '%otp=%')
    OR (response LIKE '%magic-link%' OR response LIKE '%magic_link%' OR response LIKE '%/login%token=%' OR response LIKE '%/sign-in%token=%' OR response LIKE '%/signin%token=%' OR response LIKE '%/verify%token=%' OR response LIKE '%/auth%token=%' OR response LIKE '%/reset%token=%' OR response LIKE '%/confirm%token=%' OR response LIKE '%/callback%code=%' OR response LIKE '%/login%code=%' OR response LIKE '%verification code%' OR response LIKE '%sign-in code%' OR response LIKE '%signin code%' OR response LIKE '%login code%' OR response LIKE '%security code%' OR response LIKE '%one-time code%' OR response LIKE '%one-time password%' OR response LIKE '%passcode%' OR response LIKE '%otp=%')
    OR (tool_log LIKE '%magic-link%' OR tool_log LIKE '%magic_link%' OR tool_log LIKE '%/login%token=%' OR tool_log LIKE '%/sign-in%token=%' OR tool_log LIKE '%/signin%token=%' OR tool_log LIKE '%/verify%token=%' OR tool_log LIKE '%/auth%token=%' OR tool_log LIKE '%/reset%token=%' OR tool_log LIKE '%/confirm%token=%' OR tool_log LIKE '%/callback%code=%' OR tool_log LIKE '%/login%code=%' OR tool_log LIKE '%verification code%' OR tool_log LIKE '%sign-in code%' OR tool_log LIKE '%signin code%' OR tool_log LIKE '%login code%' OR tool_log LIKE '%security code%' OR tool_log LIKE '%one-time code%' OR tool_log LIKE '%one-time password%' OR tool_log LIKE '%passcode%' OR tool_log LIKE '%otp=%'));

-- Retention rule and the replay tradeoff, recorded where the doctrine looks (CLAUDE.md: control_registry, queue_sla).
INSERT OR IGNORE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence, issue_id) VALUES
 ('ops-jobs-terminal-sweep', 'qnfo-ops worker.js scheduled(): DELETE FROM ops_jobs WHERE status IN (succeeded, failed, terminated, cancelled) AND updated_at < now - 14 days', 'guard', 'async job payloads, tool logs and responses (which can carry mail-derived text) staying in D1 for good', 0, 'keep', 'applied', 'none needed: a failure only keeps rows longer; queue_sla ops-job-terminal-retained and contract fm-ops-jobs-sweep-status-gap measure it', NULL, 'qnfo-ops 2.49.1 adds cancelled to the status list: 40 of the 49 stored rows were cancelled and never swept (oldest 2026-09-13), including the one that held a login link; migration scrub of the 7 login-shaped rows above', 100036),
 ('ops-jobs-payload-redaction', 'qnfo-ops worker.js createJobFromBody -> redactJobBody (ops_jobs.payload)', 'filter', 'login links, one-time codes and keys in tool results and model text being stored in D1', 0, 'keep', 'applied', 'system and user messages stay verbatim so the workflow replays the real request; the 14-day sweep and this migration bound what a user-typed link can keep', NULL, 'TRADEOFF: a continuation after BUDGET-AUTO-PROMOTE replays the stored copy, so it sees redacted tool output ([redacted] where a result held a code, login link or key); the budget checkpoint prompt is stored redacted, so a resumed task can lose a credential-bearing URL. Accepted because the alternative stores mailbox secrets in D1. Developer, function and function_call content is redacted like tool content (2.49.1).', 100036);

INSERT OR IGNORE INTO queue_sla (stuck_type, queue, definition, cycle_min, sla_min, auto_fix, owner, summary_column) VALUES
 ('ops-job-terminal-retained', 'ops_jobs', 'terminal ops_jobs row (succeeded, failed, terminated or cancelled) not updated for 14 days plus 120 minutes', 30, 120, 'qnfo-ops half-hourly cron deletes terminal rows older than 14 days (revert: drop the status from the sweep list)', 'qnfo-ops', 'none (a retention rule): measured by contract fm-ops-jobs-sweep-status-gap');

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('ops-jobs-sweep-status-gap',
  'a login link stored in ops_jobs stays in D1 for good because the row is cancelled and the retention sweep skips that status',
  'qnfo-ops swept ops_jobs rows with status succeeded, failed or terminated only; async jobs end as cancelled too (40 of 49 rows)',
  'qnfo-ops 2.49.1 sweeps cancelled as well and migrations/2026-10-19-ops-jobs-login-scrub.sql blanks the login-shaped terminal rows already stored',
  'no terminal ops_jobs row older than 14 days + 120 minutes, and no legacy terminal row matching a login-link or one-time-code shape',
  'fm-ops-jobs-sweep-status-gap', '2026-10-19', 100036,
  'a job status outside the sweep list holds a payload',
  'ops_jobs row job-087d227e521f4b0a8b4d08af3a5cc147 (cancelled, 2026-09-13) held a login link in tool output; 2.49.1 would have left it stored',
  'the owner mailbox login links and one-time codes readable by anyone with qnfo-audit read access');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module) VALUES
 ('fm-ops-jobs-sweep-status-gap', NULL, 'qnfo-ops 2.49.1 with cancelled in the ops_jobs sweep', 'failure-mode detector',
  'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM ops_jobs WHERE status IN (''succeeded'', ''failed'', ''terminated'', ''cancelled'') AND updated_at < strftime(''%Y-%m-%dT%H:%M:%fZ'', ''now'', ''-14 days'', ''-120 minutes'')) + (SELECT COUNT(*) FROM ops_jobs WHERE status IN (''succeeded'', ''failed'', ''terminated'', ''cancelled'') AND created_at < ''2026-10-18T00:00:00Z'' AND (payload LIKE ''%magic-link%'' OR payload LIKE ''%/login%token=%'' OR payload LIKE ''%/verify%token=%'' OR payload LIKE ''%/auth%token=%'' OR payload LIKE ''%verification code%'' OR payload LIKE ''%login code%'' OR payload LIKE ''%passcode%'')) AS TEXT) AS observed',
  'd1-query', 3, 'qnfo-ops', 1, 'active', 'failure-mode');
